+import { afterEach, beforeEach, describe, expect, it } from \"vitest\";
+import { mkdtemp, readFile, rm } from \"node:fs/promises\";
+import { tmpdir } from \"node:os\";
+import { join } from \"node:path\";
+import { addBook, finishBook, getBook, getBooks, updateBookNotes } from \"./books\";
+
+let directory;
+
+beforeEach(async () => {
+  directory = await mkdtemp(join(tmpdir(), \"dogear-test-\"));
+  process.env.BOOKS_FILE = join(directory, \"books.json\");
+});
+
+afterEach(async () => {
+  delete process.env.BOOKS_FILE;
+  await rm(directory, { recursive: true, force: true });
+});
+
+describe(\"JSON book storage\", () => {
+  it(\"starts empty and persists a new reading book\", async () => {
+    expect(await getBooks()).toEqual([]);
+
+    const book = await addBook({ title: \"A Book\", author: \"An Author\", notes: \"A note\", status: \"reading\" });
+    expect(book).toMatchObject({ title: \"A Book\", author: \"An Author\", notes: \"A note\", status: \"reading\", finishedAt: null });
+    expect(await getBook(book.id)).toEqual(book);
+    expect(JSON.parse(await readFile(process.env.BOOKS_FILE, \"utf8\"))).toEqual([book]);
+  });
+
+  it(\"marks a book as finished and updates its notes\", async () => {
+    const book = await addBook({ title: \"A Book\", author: \"An Author\", notes: \"\", status: \"reading\" });
+
+    await finishBook(book.id);
+    await updateBookNotes(book.id, \"Worth remembering.\\nAnother thought.\");
+
+    expect(await getBook(book.id)).toMatchObject({
+      status: \"finished\",
+      notes: \"Worth remembering.\\nAnother thought.\",
+      finishedAt: expect.any(String),
+    });
+  });
+
+  it(\"does not lose books when additions happen together\", async () => {
+    await Promise.all(Array.from({ length: 12 }, (_, index) => addBook({
+      title: "'`Book ${index}`,
+      author: "An Author",
+      notes: "",
+      status: "reading",
+    })));
+
+    expect(await getBooks()).toHaveLength(12);
+    expect(JSON.parse(await readFile(process.env.BOOKS_FILE, "utf8"))).toHaveLength(12);
+  });
+});
